// The session dispatches every message the protocol has; these are the ones written, asked
// at compile time so a program instantiates nothing for the rest.
template <typename Message>
inline constexpr bool writes = true;

inline void write(::omi::avro::c::Record& record, const dbn_normalized::trade_msg& message) {
    auto root = record.value().branch(0);
    if (const auto value = message.fields.price.get(); value.has_value()) { root.field(0).some().decimal(::omi::avro::c::whole(value.value())); } else { root.field(0).none(); }
    root.field(1).integer(static_cast<std::int64_t>(message.fields.size.get().value()));
    root.field(2).text(dbn_normalized::action::to_string(message.fields.action.get().value()));
    root.field(3).text(dbn_normalized::side::to_string(message.fields.side.get().value()));
    root.field(4).integer(static_cast<std::int64_t>(message.fields.flags.get().value()));
    root.field(5).integer(static_cast<std::int64_t>(message.fields.depth.get().value()));
    if (const auto value = message.fields.ts_recv.get(); value.has_value()) { root.field(6).some().decimal(::omi::avro::c::whole(value.value())); } else { root.field(6).none(); }
    root.field(7).integer(static_cast<std::int64_t>(message.fields.ts_in_delta.get().value()));
    root.field(8).integer(static_cast<std::int64_t>(message.fields.sequence.get().value()));
}

