inline void write(::omi::avro::c::Record& record, const dbn_normalized::mbp_10_msg& message) {
    auto root = record.value().branch(2);
    if (const auto value = message.fields.price.get(); value.has_value()) { root.field(0).some().decimal(::omi::avro::c::whole(value.value())); } else { root.field(0).none(); }
    root.field(1).integer(static_cast<std::int64_t>(message.fields.size.get().value()));
    root.field(2).text(dbn_normalized::action::to_string(message.fields.action.get().value()));
    root.field(3).text(dbn_normalized::side::to_string(message.fields.side.get().value()));
    root.field(4).integer(static_cast<std::int64_t>(message.fields.flags.get().value()));
    root.field(5).integer(static_cast<std::int64_t>(message.fields.depth.get().value()));
    if (const auto value = message.fields.ts_recv.get(); value.has_value()) { root.field(6).some().decimal(::omi::avro::c::whole(value.value())); } else { root.field(6).none(); }
    root.field(7).integer(static_cast<std::int64_t>(message.fields.ts_in_delta.get().value()));
    root.field(8).integer(static_cast<std::int64_t>(message.fields.sequence.get().value()));
    {
        auto bid_ask_pair_array = root.field(9).array();
        for (const auto& bid_ask_pair_entry : message.fields.bid_ask_pair) {
            auto bid_ask_pair_item = bid_ask_pair_array.item();
            if (const auto value = bid_ask_pair_entry.bid_px.get(); value.has_value()) { bid_ask_pair_item.field(0).some().decimal(::omi::avro::c::whole(value.value())); } else { bid_ask_pair_item.field(0).none(); }
            if (const auto value = bid_ask_pair_entry.ask_px.get(); value.has_value()) { bid_ask_pair_item.field(1).some().decimal(::omi::avro::c::whole(value.value())); } else { bid_ask_pair_item.field(1).none(); }
            bid_ask_pair_item.field(2).integer(static_cast<std::int64_t>(bid_ask_pair_entry.bid_sz.get().value()));
            bid_ask_pair_item.field(3).integer(static_cast<std::int64_t>(bid_ask_pair_entry.ask_sz.get().value()));
            bid_ask_pair_item.field(4).integer(static_cast<std::int64_t>(bid_ask_pair_entry.bid_ct.get().value()));
            bid_ask_pair_item.field(5).integer(static_cast<std::int64_t>(bid_ask_pair_entry.ask_ct.get().value()));
        }
        bid_ask_pair_array.close();
    }
}

